#include <stdio.h>
#include <stdlib.h>
typedef struct TreeNode {
    int val;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;
// In-order: Left ? Root ? Right
void inorder(TreeNode* root) {
    if (root == NULL) return;
    inorder(root->left);
    printf("%d ", root->val);
    inorder(root->right);
}
// Pre-order: Root ? Left ? Right
void preorder(TreeNode* root) {
    if (root == NULL) return;
    printf("%d ", root->val);
    preorder(root->left);
    preorder(root->right);
}
// Post-order: Left ? Right ? Root
void postorder(TreeNode* root) {
    if (root == NULL) return;
    postorder(root->left);
    postorder(root->right);
    printf("%d ", root->val);
}
int main() {
    // Create root node
    TreeNode* root = new TreeNode;
    root->val = 0;
    // Create left child
    root->left = new TreeNode;
    root->left->val = 1;
    root->left->left = NULL;
    root->left->right = NULL;
    // Create right child
    root->right = new TreeNode;
    root->right->val = 2;
    root->right->left = NULL;
    root->right->right = NULL;
    // Traversals
    printf("In-order traversal: ");
    inorder(root);
    printf("\n");
    printf("Pre-order traversal: ");
    preorder(root);
    printf("\n");
    printf("Post-order traversal: ");
    postorder(root);
    printf("\n");
    // Free memory
    free(root->left);
    free(root->right);
    free(root);
    return 0;
}
