    inorder(root->left);
    printf("%d  ", root->val);
    inorder(root->right);
}
// Pre-order: Root ? Left ? Right
void preorder(TreeNode* root) {
    if (root == NULL) return;
    printf("%d  ", root->val);
    preorder(root->left);
    preorder(root->right);
}
// Post-order: Left ? Right  ? Root
void postorder(TreeNode*  root) {
    if (root == NULL) return;
    postorder(root->left);
    postorder(root->right);
    printf("%d  ", root->val);
}
